async function test() {
  const content = `<|user|>Browse IT jobs with certificate Security clearance
<|assistant|>1. Type "IT jobs" into "Search by job title, skill or company"
2. Click "Search"
3. Click " Filters"
4. Click "Certificates"
5. Click "Security clearance"
6. Click "Display Results"`;
